type UseDesktopNavigationArgs = {
  onAppModeChange: Dispatch<SetStateAction<AppMode>>;
  onOpenPinnedFolder: (path: string) => void;
  openDesktopContextMenu: (state: DesktopContextMenuState) => void;
  closeDesktopContextMenu: () => void;
  handleNoteClick: (
    notePath: string,
    event: ReactMouseEvent,
    parentPath?: string
  ) => void;
  handleNoteContextMenu: (
    event: ReactMouseEvent,
    notePath: string,
    parentPath?: string
  ) => Promise<void>;
};

export function useDesktopNavigation({
  onAppModeChange,
  onOpenPinnedFolder,
  openDesktopContextMenu,
  closeDesktopContextMenu,
  handleNoteClick,
  handleNoteContextMenu,
}: UseDesktopNavigationArgs) {
  const { clearNote } = useEditor();
  const {
    treeData,
    notes,
    notePreviews,
    activeNode,
    activeFeedGroup,
    setActiveFeedGroup,
    activeFeedNode,
    feedNotes,
    feedNotePreviews,
    deleteNotes,
    moveNotesToArchive,
