import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type Dispatch,
  type MouseEvent as ReactMouseEvent,
  type SetStateAction,
} from "react";
import { useShallow } from "zustand/react/shallow";

import type { DesktopContextMenuState } from "@/app/hooks/use-tree-interactions";
import { useSelection } from "@/app/state/selection-store";
import { useEditor } from "@/features/notes/editor/hooks/editor-context";
import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
import { FEED_FOLDER_PATH, isSystemFolder } from "@typenotes/shared/constants";
import { computeRangeSelection } from "@/shared/lib/selection";
import type { AppMode } from "@typenotes/shared/types";

type UseDesktopNavigationArgs = {
  onAppModeChange: Dispatch<SetStateAction<AppMode>>;
  onOpenPinnedFolder: (path: string) => void;
  openDesktopContextMenu: (state: DesktopContextMenuState) => void;
  closeDesktopContextMenu: () => void;
  handleNoteClick: (
    notePath: string,
    event: ReactMouseEvent,
    parentPath?: string
  ) => void;
  handleNoteContextMenu: (
    event: ReactMouseEvent,
    notePath: string,
    parentPath?: string
  ) => Promise<void>;
};

export function useDesktopNavigation({
  onAppModeChange,
  onOpenPinnedFolder,
  openDesktopContextMenu,
  closeDesktopContextMenu,
  handleNoteClick,
  handleNoteContextMenu,
}: UseDesktopNavigationArgs) {
  const { clearNote } = useEditor();
  const {
    treeData,
    notes,
    notePreviews,
    activeNode,
    activeFeedGroup,
    setActiveFeedGroup,
    activeFeedNode,
    feedNotes,
    feedNotePreviews,
    deleteNotes,
    moveNotesToArchive,
  } = useNotesTree();
  const {
    activeFolder,
    activeNote,
    selectedNotes,
    lastSelectedNote,
    selectNote,
    resetSelection,
    setSelectedFolders,
    setLastSelectedFolder,
    setActiveFolder,
    setSelectedNotes,
    setLastSelectedNote,
    setActiveNote,
  } = useSelection(
    useShallow((state) => ({
      activeFolder: state.activeFolder,
      activeNote: state.activeNote,
      selectedNotes: state.selectedNotes,
      lastSelectedNote: state.lastSelectedNote,
      selectNote: state.selectNote,
      resetSelection: state.resetSelection,
      setSelectedFolders: state.setSelectedFolders,
      setLastSelectedFolder: state.setLastSelectedFolder,
      setActiveFolder: state.setActiveFolder,
      setSelectedNotes: state.setSelectedNotes,
      setLastSelectedNote: state.setLastSelectedNote,
      setActiveNote: state.setActiveNote,
    }))
  );

  const customFoldersTreeData = useMemo(
    () => treeData.filter((node) => !isSystemFolder(node.id)),
    [treeData]
  );

  const [activeNavigationTab, setActiveNavigationTab] = useState<"feed" | "folders">(
    "folders"
  );
  // Feed is a transient view. Remember the last real folder so "back to folders"
  // has a stable place to land instead of guessing from the current tree.
  const lastNonFeedFolderRef = useRef<string>("");
  const selectedNotesRef = useRef<Set<string>>(new Set());
  selectedNotesRef.current = selectedNotes;

  useEffect(() => {
    if (activeFolder && activeFolder !== FEED_FOLDER_PATH) {
      lastNonFeedFolderRef.current = activeFolder;
    }
  }, [activeFolder]);

  useEffect(() => {
    if (activeFolder === FEED_FOLDER_PATH && activeNavigationTab !== "feed") {
      setActiveNavigationTab("feed");
      return;
    }
    if (activeFolder !== FEED_FOLDER_PATH && activeNavigationTab === "feed") {
      setActiveNavigationTab("folders");
    }
  }, [activeFolder, activeNavigationTab]);

  const selectedNotePaths = useCallback(() => {
    const selected = selectedNotesRef.current;
    return (
      activeNote && !selected.has(activeNote)
        ? [activeNote]
        : selected.size > 0
          ? Array.from(selected)
          : activeNote
            ? [activeNote]
            : []
    );
  }, [activeNote]);

  const moveSelectedNotesToTrashByShortcut = useCallback(() => {
    const paths = selectedNotePaths();
    if (paths.length > 0) {
      void moveNotesToArchive(paths);
    }
  }, [moveNotesToArchive, selectedNotePaths]);

  const deleteSelectedNotesByShortcut = useCallback(() => {
    const paths = selectedNotePaths();
    if (paths.length > 0) {
      void deleteNotes(paths);
    }
  }, [deleteNotes, selectedNotePaths]);

  const openFeedTab = useCallback(() => {
    closeDesktopContextMenu();
    onAppModeChange("notes");
    if (activeFolder && activeFolder !== FEED_FOLDER_PATH) {
      lastNonFeedFolderRef.current = activeFolder;
    }
    setActiveNavigationTab("feed");
    onOpenPinnedFolder(FEED_FOLDER_PATH);
  }, [activeFolder, closeDesktopContextMenu, onAppModeChange, onOpenPinnedFolder]);

  const openFoldersTab = useCallback(() => {
    closeDesktopContextMenu();
    onAppModeChange("notes");
    setActiveNavigationTab("folders");
    const fallbackFolder =
      lastNonFeedFolderRef.current || customFoldersTreeData[0]?.id || "";
    if (fallbackFolder) {
      onOpenPinnedFolder(fallbackFolder);
      return;
    }
    resetSelection();
    clearNote();
  }, [
    clearNote,
    closeDesktopContextMenu,
    customFoldersTreeData,
    onAppModeChange,
    onOpenPinnedFolder,
    resetSelection,
  ]);

  const handleFeedMiddleNoteClick = useCallback(
    (notePath: string, event: ReactMouseEvent) => {
      const notePaths = feedNotes.map((note) => note.path);
      selectNote(
        notePath,
        FEED_FOLDER_PATH,
        computeRangeSelection(event, selectedNotes, notePaths, lastSelectedNote, notePath)
      );
      setActiveFeedGroup(activeFeedGroup || activeFeedNode?.id || "");
      setActiveNavigationTab("feed");
    },
    [
      activeFeedGroup,
      activeFeedNode?.id,
      feedNotes,
      lastSelectedNote,
      selectNote,
      setActiveFeedGroup,
      selectedNotes,
    ]
  );

  const handleFeedMiddleNoteContextMenu = useCallback(
    (event: ReactMouseEvent, notePath: string) => {
      event.preventDefault();
      event.stopPropagation();
      const notePaths = feedNotes.map((note) => note.path);
      const targetPaths =
        selectedNotes.size > 1 && selectedNotes.has(notePath)
          ? Array.from(selectedNotes)
          : [notePath];
      setSelectedFolders(new Set([FEED_FOLDER_PATH]));
      setLastSelectedFolder(FEED_FOLDER_PATH);
      setActiveFolder(FEED_FOLDER_PATH);
      // Keeps the existing multi-selection (and its range anchor) when the
      // target note is already part of it.
      if (!selectedNotes.has(notePath)) {
        setSelectedNotes(new Set([notePath]));
        setLastSelectedNote(notePath);
      }
      setActiveNote(notePath);
      setActiveFeedGroup(activeFeedGroup || activeFeedNode?.id || "");
      setActiveNavigationTab("feed");
      openDesktopContextMenu({
        kind: "note",
        x: event.clientX,
        y: event.clientY,
        path: notePath,
        parentPath: activeFeedGroup || activeFeedNode?.id || FEED_FOLDER_PATH,
        targetPaths: targetPaths.length > 0 ? targetPaths : notePaths,
      });
    },
    [
      activeFeedGroup,
      activeFeedNode?.id,
      feedNotes,
      openDesktopContextMenu,
      selectedNotes,
      setActiveFeedGroup,
      setActiveFolder,
      setActiveNote,
      setLastSelectedFolder,
      setLastSelectedNote,
      setSelectedFolders,
      setSelectedNotes,
    ]
  );

  // The middle pane mirrors whichever list is active in the desktop tabs.
  const middlePaneNotes = useMemo(
    () => (activeNavigationTab === "feed" ? feedNotes : notes),
    [activeNavigationTab, feedNotes, notes]
  );
  const middlePaneNotePreviews = useMemo(
    () => (activeNavigationTab === "feed" ? feedNotePreviews : notePreviews),
    [activeNavigationTab, feedNotePreviews, notePreviews]
  );
  const middlePaneTitle = useMemo(
    () =>
      activeNavigationTab === "feed"
        ? activeFeedNode?.name || "Feed"
        : activeNode?.name || activeFolder || "Notes",
    [activeFeedNode?.name, activeFolder, activeNavigationTab, activeNode?.name]
  );
  // Feed needs to rewrite selection into its own group; folder notes can use the
  // tree interaction handlers directly.
  const middlePaneNoteClick = useCallback(
    (notePath: string, event: ReactMouseEvent, parentPath?: string) => {
      if (activeNavigationTab === "feed") {
        handleFeedMiddleNoteClick(notePath, event);
        return;
      }
      handleNoteClick(notePath, event, parentPath);
    },
    [activeNavigationTab, handleFeedMiddleNoteClick, handleNoteClick]
  );
  const middlePaneNoteContextMenu = useCallback(
    async (event: ReactMouseEvent, notePath: string, parentPath?: string) => {
      if (activeNavigationTab === "feed") {
        handleFeedMiddleNoteContextMenu(event, notePath);
        return;
      }
      await handleNoteContextMenu(event, notePath, parentPath);
    },
    [activeNavigationTab, handleFeedMiddleNoteContextMenu, handleNoteContextMenu]
  );

  return {
    activeNavigationTab,
    customFoldersTreeData,
    moveSelectedNotesToTrashByShortcut,
    deleteSelectedNotesByShortcut,
    openFeedTab,
    openFoldersTab,
    middlePaneNotes,
    middlePaneNotePreviews,
    middlePaneTitle,
    middlePaneNoteClick,
    middlePaneNoteContextMenu,
  };
}
    [setRenamingFolder, setRenameValue]
  );

  const submitRenameFolder = useCallback(async () => {
    if (!renamingFolder || !renameValue.trim()) {
      setRenamingFolder(null);
      return;
    }
    const oldPath = renamingFolder;
    const newPath = await api.renameItem(oldPath, renameValue.trim());
    setRenamingFolder(null);
    setRenameValue("");
    await refreshTree();
    applyFolderRename(oldPath, newPath);
  }, [applyFolderRename, refreshTree, renamingFolder, renameValue, setRenamingFolder, setRenameValue]);

  const cancelRenameFolder = useCallback(() => {
    setRenamingFolder(null);
    setRenameValue("");
  }, [setRenamingFolder, setRenameValue]);

  const deleteFolders = useCallback(
    async (paths: string[]) => {
      if (paths.length === 0) return;
      if (paths.some(isSystemFolder)) {
        window.alert(`"Feed" and "Archieve" are fixed folders and cannot be deleted.`);
        return;
      }
      const confirmed = await confirmAction(`Delete ${paths.length} folder(s)?`);
      if (!confirmed) return;
      const removedIds = new Set(
        visibleNavigationItems
          .filter((item) =>
            paths.some((path) => item.id === path || item.id.startsWith(`${path}/`))
          )
          .map((item) => item.id)
      );
      const nextTarget = findPostDeletionNavigationTarget(
        visibleNavigationItems,
        removedIds
      );
      await api.deleteItems(paths);
      await refreshTree();
      selectPostDeletionTarget(nextTarget, false);
    },
    [refreshTree, selectPostDeletionTarget, visibleNavigationItems]
  );

  const deleteNotes = useCallback(
    async (paths: string[]) => {
      if (paths.length === 0) return false;
      const confirmed = await confirmAction(`Delete ${paths.length} note(s)?`);
      if (!confirmed) return false;
      const fromFeed = activeFolder === FEED_FOLDER_PATH;
      const nestedNavigationItems = fromFeed
        ? feedVisibleNavigationItems
        : visibleNavigationItems;
      const navigationItems = nestedNavigationItems.some((item) =>
        paths.includes(item.id)
      )
        ? nestedNavigationItems
        : (fromFeed ? feedNotes : notes).map((note) => ({
            type: "note" as const,
            id: note.path,
            parentId: fromFeed ? FEED_FOLDER_PATH : activeFolder,
          }));
      const nextTarget = findPostDeletionNavigationTarget(
        navigationItems,
        new Set(paths)
      );
      await api.deleteItems(paths);
      await refreshTree();
      selectPostDeletionTarget(nextTarget, fromFeed);
      return true;
    },
    [
      activeFolder,
      feedNotes,
      feedVisibleNavigationItems,
      notes,
      refreshTree,
      selectPostDeletionTarget,
      visibleNavigationItems,
    ]
  );

  const moveNotesToArchive = useCallback(
    async (paths: string[]) => {
      if (paths.length === 0) return;
      await api.moveItems(paths, ARCHIEVE_FOLDER_PATH);
      selectFolder(ARCHIEVE_FOLDER_PATH);
      clearNote();
      await refreshTree();
    },
    [clearNote, refreshTree, selectFolder]
  );
import { useEffect } from "react";
import { useShallow } from "zustand/react/shallow";
import type { AppMode, PaneId } from "@typenotes/shared/types";
import { useAppearance } from "@/app/state/appearance-store";
import { useEditor } from "@/features/notes/editor/hooks/editor-context";
import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
import { focusNoScroll } from "@/shared/lib/dom";

type UsePaneShortcutsArgs = {
  appMode: AppMode;
  sidebarCollapsed: boolean;
  setSidebarCollapsed: React.Dispatch<React.SetStateAction<boolean>>;
  moveSelectedNotesToTrash: () => void;
  deleteSelectedNotes: () => void;
  lockAppNow: () => Promise<void>;
  foldersPanelRef: React.RefObject<HTMLDivElement | null>;
  middlePaneRef: React.RefObject<HTMLDivElement | null>;
  lastLeftPaneFocusRef: React.MutableRefObject<"folders" | "middle">;
};

/**
 * Desktop global keyboard shortcuts and pane focus management:
 * cmd/ctrl + T (toggle sidebar), W (toggle navigation/editor), K/J (cycle all panes),
 * N (new note), Backspace (move to trash), shift+Backspace (delete), +/-/0
 * (editor font size), shift+L (lock).
 * Tracks the last-focused left pane so toggling the sidebar can restore it.
 */
export function usePaneShortcuts({
  appMode,
  sidebarCollapsed,
  setSidebarCollapsed,
  moveSelectedNotesToTrash,
  deleteSelectedNotes,
  lockAppNow,
  foldersPanelRef,
  middlePaneRef,
  lastLeftPaneFocusRef,
}: UsePaneShortcutsArgs) {
  const { rightPaneRef } = useEditor();
  const { createNewNote, shouldNestNotesInNavigation } = useNotesTree();
  const { increaseEditorFontSize, decreaseEditorFontSize, resetEditorFontSize } =
    useAppearance(
      useShallow((state) => ({
        increaseEditorFontSize: state.increaseEditorFontSize,
        decreaseEditorFontSize: state.decreaseEditorFontSize,
        resetEditorFontSize: state.resetEditorFontSize,
      }))
    );

  useEffect(() => {
    const hasMiddlePane = appMode !== "notes" || !shouldNestNotesInNavigation;

    const getFocusedPane = (): PaneId | null => {
      const activeElement = document.activeElement as HTMLElement | null;
      if (!activeElement) return null;
      if (
        foldersPanelRef.current &&
        (activeElement === foldersPanelRef.current ||
          foldersPanelRef.current.contains(activeElement))
      )
        return "folders";
      if (
        middlePaneRef.current &&
        (activeElement === middlePaneRef.current ||
          middlePaneRef.current.contains(activeElement))
      )
        return "middle";
      if (
        rightPaneRef.current &&
        (activeElement === rightPaneRef.current ||
          rightPaneRef.current.contains(activeElement))
      )
        return "right";
      return null;
    };

    const focusPane = (pane: PaneId) => {
      if (pane === "folders") {
        focusNoScroll(foldersPanelRef.current);
        return;
      }
      if (pane === "middle") {
        if (!hasMiddlePane) {
          focusNoScroll(foldersPanelRef.current);
          return;
        }
        const settingsSection =
          appMode === "settings"
            ? middlePaneRef.current?.querySelector<HTMLElement>(
                ".settings-nav-row.is-selected"
              )
            : null;
        focusNoScroll(settingsSection || middlePaneRef.current);
        return;
      }
      const editorElement =
        appMode === "notes"
          ? rightPaneRef.current?.querySelector<HTMLElement>(
              ".tiptap-content[contenteditable='true']"
            ) || rightPaneRef.current
          : rightPaneRef.current;
      focusNoScroll(editorElement);
    };

    const handleGlobalKeyDown = (event: KeyboardEvent) => {
      if (!(event.metaKey || event.ctrlKey) || event.altKey || event.repeat) return;
      const code = event.code;
      const isLockShortcut = code === "KeyL" && event.shiftKey;
      if (
        code !== "KeyT" &&
        code !== "KeyW" &&
        code !== "KeyK" &&
        code !== "KeyJ" &&
        code !== "KeyN" &&
        code !== "Backspace" &&
        code !== "Equal" &&
        code !== "Minus" &&
        code !== "Digit0" &&
        code !== "NumpadAdd" &&
        code !== "NumpadSubtract" &&
        code !== "Numpad0" &&
        !isLockShortcut
      )
        return;
      event.preventDefault();

      if (code === "Equal" || code === "NumpadAdd") {
        if (appMode === "notes") increaseEditorFontSize();
        return;
      }
      if (code === "Minus" || code === "NumpadSubtract") {
        if (appMode === "notes") decreaseEditorFontSize();
        return;
      }
      if (code === "Digit0" || code === "Numpad0") {
        if (appMode === "notes") resetEditorFontSize();
        return;
      }
      if (code === "KeyN") {
        void createNewNote();
        return;
      }
      if (isLockShortcut) {
        void lockAppNow();
        return;
      }
      if (code === "Backspace") {
        if (appMode === "notes") {
          if (event.shiftKey) deleteSelectedNotes();
          else moveSelectedNotesToTrash();
        }
        return;
      }
      if (code === "KeyT") {
        const currentPane = getFocusedPane();
        setSidebarCollapsed((prev) => {
          const next = !prev;
          if (next) {
            if (currentPane === "folders" || currentPane === "middle")
              lastLeftPaneFocusRef.current = currentPane;
            requestAnimationFrame(() => focusPane("right"));
          } else {
            requestAnimationFrame(() => focusPane(lastLeftPaneFocusRef.current));
          }
          return next;
        });
        return;
      }
      if (code === "KeyW") {
        const navigationPane: "folders" | "middle" =
          appMode === "settings" ? "middle" : "folders";
        if (sidebarCollapsed && navigationPane === "folders") {
          setSidebarCollapsed(false);
          lastLeftPaneFocusRef.current = navigationPane;
          requestAnimationFrame(() => focusPane(navigationPane));
          return;
        }
        const currentPane = getFocusedPane();
        if (currentPane === "right") {
          lastLeftPaneFocusRef.current = navigationPane;
          focusPane(navigationPane);
        } else {
          focusPane("right");
        }
        return;
      }

      const panes: PaneId[] = sidebarCollapsed
        ? ["right"]
        : hasMiddlePane
          ? ["folders", "middle", "right"]
          : ["folders", "right"];
      const currentPane = getFocusedPane();
      const startPane =
        currentPane && panes.includes(currentPane)
          ? currentPane
          : hasMiddlePane
            ? "middle"
            : "folders";
      const delta = code === "KeyK" ? 1 : -1;
      const nextIndex = Math.max(
        0,
        Math.min(panes.length - 1, panes.indexOf(startPane) + delta)
      );
      const targetPane = panes[nextIndex];
      if (targetPane === "folders" || targetPane === "middle")
        lastLeftPaneFocusRef.current = targetPane;
      focusPane(targetPane);
    };

    window.addEventListener("keydown", handleGlobalKeyDown);
    return () => window.removeEventListener("keydown", handleGlobalKeyDown);
  }, [
    appMode,
    createNewNote,
    deleteSelectedNotes,
    moveSelectedNotesToTrash,
    decreaseEditorFontSize,
    foldersPanelRef,
    increaseEditorFontSize,
    middlePaneRef,
    resetEditorFontSize,
    rightPaneRef,
    lockAppNow,
    setSidebarCollapsed,
    shouldNestNotesInNavigation,
    sidebarCollapsed,
    lastLeftPaneFocusRef,
  ]);
}

