// The Feed and Folders panes render the same thing: a flat list of visible
// folder/note rows derived from a nested tree. This module owns that shape —
// building the rows from any NavigationNode tree, and moving the selection
// through them with the arrow keys. Folder trees and feed buckets share it.
import type { VisibleNavigationItem } from "@typenotes/shared/types";
import type { NavigationNode } from "./types";

export function buildVisibleNavigationItems(
  nodes: NavigationNode[],
  expanded: Set<string>,
  includeNotes: boolean
): VisibleNavigationItem[] {
  const items: VisibleNavigationItem[] = [];

  const walk = (level: NavigationNode[], parentId: string | null) => {
    level.forEach((node) => {
      items.push({
        type: "folder",
        id: node.id,
        parentId,
      });

      const noteRows = includeNotes ? node.notes ?? [] : [];
      const hasNestedItems = node.children.length > 0 || noteRows.length > 0;
      if (!hasNestedItems || !expanded.has(node.id)) {
        return;
      }

      noteRows.forEach((note) => {
        items.push({
          type: "note",
          id: note.path,
          parentId: node.id,
        });
      });

      walk(node.children, node.id);
    });
  };

  walk(nodes, null);
  return items;
}

export type NavigationKey = "ArrowUp" | "ArrowDown" | "ArrowLeft" | "ArrowRight";

export function findPostDeletionNavigationTarget(
  items: VisibleNavigationItem[],
  removedIds: ReadonlySet<string>
): VisibleNavigationItem | null {
  const firstRemovedIndex = items.findIndex((item) => removedIds.has(item.id));
  if (firstRemovedIndex < 0) {
    return null;
  }

  const remainingItems = items.filter((item) => !removedIds.has(item.id));
  if (remainingItems.length === 0) {
    return null;
  }

  // Keep the same row index after deletion. At the bottom edge this naturally
  // falls back to the preceding row.
  return remainingItems[Math.min(firstRemovedIndex, remainingItems.length - 1)];
}

export type NavigateVisibleItemsDeps = {
  items: VisibleNavigationItem[];
  /**
   * Selection anchors, most specific first; the first one present in `items`
   * is the row navigation starts from (falling back to the first row).
   */
  preferredIds: Array<string | null>;
  expanded: Set<string>;
  hasNestedItems: (folderId: string) => boolean;
  expand: (folderId: string) => void;
  collapse: (folderId: string) => void;
  selectFolder: (folderId: string) => void;
  selectNote: (notePath: string, parentId: string) => void;
};

/**
 * Arrow-key navigation over a visible-rows list: up/down move the selection,
 * right expands a folder (then enters its first child), left collapses (then
 * climbs to the parent). Notes jump back to their parent folder on left.
 */
export function navigateVisibleItems(
  key: NavigationKey,
  {
    items,
    preferredIds,
    expanded,
    hasNestedItems,
    expand,
    collapse,
    selectFolder,
    selectNote,
  }: NavigateVisibleItemsDeps
): void {
  if (items.length === 0) {
    return;
  }
  const navIds = items.map((item) => item.id);
  const current =
    preferredIds.find((id): id is string => Boolean(id && navIds.includes(id))) ??
    navIds[0];
  const currentIndex = navIds.indexOf(current);
  const currentEntry = items[currentIndex];
  if (!currentEntry) {
    return;
  }

  const selectEntry = (entry: VisibleNavigationItem) => {
    if (entry.type === "folder") {
      selectFolder(entry.id);
      return;
    }
    selectNote(entry.id, entry.parentId);
  };

  if (key === "ArrowUp" || key === "ArrowDown") {
    const delta = key === "ArrowUp" ? -1 : 1;
    const nextIndex = Math.max(0, Math.min(items.length - 1, currentIndex + delta));
    const nextEntry = items[nextIndex];
    if (nextEntry) {
      selectEntry(nextEntry);
    expect(items.every((item) => item.type === "folder")).toBe(true);
  });

  it("does not descend into an expanded folder with no visible rows", () => {
    const items = buildVisibleNavigationItems(tree, new Set(["work"]), false);
    expect(items.map((item) => item.id)).toEqual(["personal", "work"]);
  });
});

describe("findPostDeletionNavigationTarget", () => {
  const items = buildVisibleNavigationItems(
    tree,
    new Set(["personal", "personal/journal"]),
    true
  );

  it("selects the row that takes the deleted row's place", () => {
    expect(
      findPostDeletionNavigationTarget(
        items,
        new Set(["personal/todo.md"])
      )?.id
    ).toBe("personal/journal");
  });

  it("falls back to the previous row when deleting the final row", () => {
    expect(
      findPostDeletionNavigationTarget(items, new Set(["work"]))?.id
    ).toBe("personal/journal/a.md");
  });

  it("handles deletion of multiple visible rows", () => {
    expect(
      findPostDeletionNavigationTarget(
        items,
        new Set(["personal/todo.md", "personal/journal"])
      )?.id
    ).toBe("personal/journal/a.md");
  });
});

describe("navigateVisibleItems", () => {
  type DepsOverrides = Partial<
    Pick<NavigateVisibleItemsDeps, "items" | "preferredIds" | "expanded">
  >;

  const makeDeps = (overrides: DepsOverrides = {}) => ({
    items: buildVisibleNavigationItems(tree, new Set(["personal"]), true),
    preferredIds: [] as Array<string | null>,
    expanded: new Set(["personal"]),
    hasNestedItems: (id: string) => id === "personal" || id === "personal/journal",
    expand: vi.fn<(folderId: string) => void>(),
    collapse: vi.fn<(folderId: string) => void>(),
    selectFolder: vi.fn<(folderId: string) => void>(),
    selectNote: vi.fn<(notePath: string, parentId: string) => void>(),
    ...overrides,
  });

  const navigate = (key: NavigationKey, deps: NavigateVisibleItemsDeps) =>
    navigateVisibleItems(key, deps);

      setSelectedFolders,
      setSelectedNotes,
      tree,
    ]
  );

  const showNoteInfo = useCallback(async (path: string) => {
    try {
      const meta = await api.getNoteMeta(path);
      const createdLabel = meta.created_ms
        ? new Date(meta.created_ms).toLocaleString()
        : "—";
      const updatedLabel = meta.updated_ms
        ? new Date(meta.updated_ms).toLocaleString()
        : "—";
      const archivedLabel = meta.archived_ms
        ? new Date(meta.archived_ms).toLocaleString()
        : "—";
      const reviewedLabel = meta.reviewed_ms
        ? new Date(meta.reviewed_ms).toLocaleString()
        : "—";
      window.alert(
        `Created: ${createdLabel}\nUpdated: ${updatedLabel}\nArchived: ${archivedLabel}\nReviewed: ${reviewedLabel}`
      );
    } catch (error) {
      console.error("[notes] failed to show note info", error);
    }
  }, []);

  return {
    createNewNote,
    deleteFolders,
    deleteNotes,
    moveNotesToArchive,
    moveNotesToFolder,
    updateNoteMarkers,
    flattenIntoFeed,
    showNoteInfo,
    startRenameFolder,
    submitRenameFolder,
    cancelRenameFolder,
  };
}
